import 'dart:convert';
import 'dart:io';
import 'package:live_jury_room/core/data/demo_cases.dart';

void main() {
  final out = StringBuffer(
    '-- Original fictional case library. Generated by dart run tool/export_case_seed.dart\nbegin;\n',
  );
  for (final c in demoCases) {
    final json = jsonEncode(c.toJson()).replaceAll("'", "''");
    out.writeln(
      "insert into public.cases(id,payload) values('${c.id}','$json'::jsonb) on conflict(id) do update set payload=excluded.payload;",
    );
  }
  out.writeln('commit;');
  File(
    'supabase/migrations/202609060002_case_library.sql',
  ).writeAsStringSync(out.toString());
}
